changeSet.sql:
CREATE OR REPLACE FUNCTION nexus.catalog_collections_owner_from_docs()
    RETURNS TRIGGER
    LANGUAGE plpgsql
    SECURITY INVOKER
AS $fn$
DECLARE
    v_owner text;
BEGIN
    IF NEW.content_type IN ('code', 'docs', 'rdr')
       AND NEW.owner_id !~ '^[0-9]+(-[0-9]+)*$' THEN
        v_owner := nexus.catalog_collection_doc_owner(NEW.tenant_id, NEW.name);
        IF v_owner IS NOT NULL THEN
            NEW.owner_id := v_owner;
        END IF;
    END IF;
    RETURN NEW;
END;
$fn$;

DROP TRIGGER IF EXISTS catalog_collections_owner_from_docs ON nexus.catalog_collections;
CREATE TRIGGER catalog_collections_owner_from_docs
    BEFORE INSERT OR UPDATE OF owner_id, content_type ON nexus.catalog_collections
    FOR EACH ROW EXECUTE FUNCTION nexus.catalog_collections_owner_from_docs();

CREATE OR REPLACE FUNCTION nexus.catalog_documents_owner_to_collection()
    RETURNS TRIGGER
    LANGUAGE plpgsql
    SECURITY INVOKER
AS $fn$
BEGIN
    IF NEW.deleted_at IS NULL
       AND NEW.physical_collection <> ''
       AND NEW.tumbler ~ '^[0-9]+\.[0-9]+\.[0-9]+' THEN
        UPDATE nexus.catalog_collections c
           SET owner_id = COALESCE(nexus.catalog_collection_doc_owner(c.tenant_id, c.name), c.owner_id)
         WHERE c.tenant_id = NEW.tenant_id
           AND c.name = NEW.physical_collection
           AND c.content_type IN ('code', 'docs', 'rdr')
           AND c.owner_id !~ '^[0-9]+(-[0-9]+)*$';
    END IF;
    RETURN NULL;
END;
$fn$;

DROP TRIGGER IF EXISTS catalog_documents_owner_to_collection ON nexus.catalog_documents;
CREATE TRIGGER catalog_documents_owner_to_collection
    AFTER INSERT OR UPDATE OF physical_collection, deleted_at ON nexus.catalog_documents
    FOR EACH ROW EXECUTE FUNCTION nexus.catalog_documents_owner_to_collection();

rollback.sql:
DROP TRIGGER IF EXISTS catalog_documents_owner_to_collection ON nexus.catalog_documents;
DROP TRIGGER IF EXISTS catalog_collections_owner_from_docs ON nexus.catalog_collections;
DROP FUNCTION IF EXISTS nexus.catalog_documents_owner_to_collection();
DROP FUNCTION IF EXISTS nexus.catalog_collections_owner_from_docs();

changeSet.sql:
ALTER TABLE nexus.catalog_collections NO FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.catalog_documents NO FORCE ROW LEVEL SECURITY;

DO $$
DECLARE
    v_repaired BIGINT;
BEGIN
    UPDATE nexus.catalog_collections c
       SET owner_id = nexus.catalog_collection_doc_owner(c.tenant_id, c.name)
     WHERE c.content_type IN ('code', 'docs', 'rdr')
       AND c.owner_id !~ '^[0-9]+(-[0-9]+)*$'
       AND nexus.catalog_collection_doc_owner(c.tenant_id, c.name) IS NOT NULL;
    GET DIAGNOSTICS v_repaired = ROW_COUNT;
    RAISE NOTICE 'catalog-044-3: re-derived owner_id from documents for % collection row(s)', v_repaired;
END $$;

ALTER TABLE nexus.catalog_documents FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.catalog_collections FORCE ROW LEVEL SECURITY;
